/* release monster from bag of tricks; return number of monsters created */
/**
 * @param {$T.obj | null} bag struct obj *
 * @param {number} tipping boolean
 * @param {*} seencount int *
 * @returns {Promise<number>} int
 */
export async function bagotricks(bag, tipping, seencount) {   // makemon.c:2554
    /* caller emptying entirely; affects shop handling */
    /* secondary output */
    let moncount = 0;
    if (!bag || bag.otyp !== BAG_OF_TRICKS) {
        await impossible($c.lit("bad bag o' tricks"));
    } else if (bag.spe < 1) {
        /* if tipping known empty bag, give normal empty container message */
        await pline($c.lit("%s"), tipping && bag.cknown ? $c.lit("It's empty.") : c_common_strings.c_nothing_happens);
        /* now known to be empty if sufficiently discovered */
        if (bag.dknown && objects[bag.otyp].oc_name_known) {
            bag.cknown = 1;
            await update_inventory();   /* for perm_invent */
        }
    } else {
        let creatcnt = 1;
        let seecount = 0;
        await consume_obj_charge(bag, !tipping ? 1 : 0);
        if (!rn2(23)) {
            creatcnt = creatcnt + rnd(7) | 0;
        }
        do {
            const mtmp = await makemon(null, u.ux, u.uy, NO.MM_FLAGS);
            if (mtmp) {
                moncount = moncount + 1 | 0;
                if (canseemon(mtmp) && (M_AP_TYPE(mtmp) === M_AP.NOTHING || M_AP_TYPE(mtmp) === M_AP.MONSTER) || sensemon(mtmp)) {
                    seecount = seecount + 1 | 0;
                }
            }
        } while ((creatcnt = creatcnt - 1 | 0) > 0);
        if (seecount) {
            if (seencount) {
                seencount.set(0, seencount.get(0) + seecount | 0);
            }
            if (bag.dknown) {
                await discover_object(BAG_OF_TRICKS, TRUE, TRUE, TRUE);
                await update_inventory();   /* for perm_invent */
            }
        } else if (!tipping) {
            await pline($c.lit("%s"), !moncount ? c_common_strings.c_nothing_happens : c_common_strings.c_nothing_seems_to_happen);
        }
    }
    return moncount;
}
/* create some or all remaining erinyes around the player */
/**
 * @param {number} limit int
 * @returns {Promise<void>}
 */
export async function summon_furies(limit) {   // makemon.c:2605
    /* number to create, or 0 to create until extinct */
    let i = 0;
    while (mk_gen_ok(PM.ERINYS, G_GONE, 0) && (i < limit || !limit)) {
        await makemon(mons[PM.ERINYS], u.ux, u.uy, MM.ADJACENTOK | MM.NOWAIT);
        i = i + 1 | 0;
    }
}

